# -*- coding: utf-8 -*-
from pathlib import Path
import json,re,shutil,html
ROOT=Path(__file__).resolve().parents[1];root=ROOT/'experiments/C2_flip';pub=ROOT/'work/github-pages-peers2002';d=json.loads((root/'tables/analysis.json').read_text())
names=dict(zip(['reflect','job','illness','kids','petq','hobby','buy','partner','kidwed','temper','stranger','retire','babycare','wedtalk','loan','kidsick','jobchange','diag','invest','school3','discipline','nbrkid','care','rankup','college','thanks','kinask','drink','school2','lotto'],['暂停片刻','选择工作','生病就医','是否生育','养宠物','兴趣选择','购买物品','相亲恋爱','子女婚礼','脾气与冲突','陌生人的请求','退休','育儿照料','谈婚论嫁','借贷','孩子就医','更换工作','诊断治疗','理财','升学分流','管教孩子','邻家孩子','照护父母','晋升','大学路径','表达感谢','亲戚求助','饮酒','继续读书','彩票']))
css=re.search(r'<style>(.*?)</style>',(ROOT/'scripts/policy_report.template.html').read_text(),re.S)[1]
top=sorted(d['rankings'],key=lambda r:r['effect']['abs_life']['mean'],reverse=True)[0]
head=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>改选一次，人生会怎样？ · 人生模拟实验室</title><style>{css}td.wrap{{white-space:normal;min-width:200px}}.chips{{display:flex;flex-wrap:wrap;gap:8px}}.chips span{{background:#e8ebdf;padding:3px 9px}}button{{cursor:pointer}}</style></head><body><main><a href="index.html">← 人生模拟实验室</a><header><span class="eyebrow">C2_FLIP / ENGINE 0.8.30</span><h1>改选一次，人生会怎样？</h1><p>30种常见抉择，每类500次改选。先核对分岔前一致，再看路径改变了多少，以及是变好还是变坏。</p><div class="grid"><div><div class="big">15,000</div>改选人生，与A报告原人生配对</div><div><div class="big">{d['unique_seeds']:,}</div>不同的原始seed，多类抉择复用同一人</div><div><div class="big">{d['audit']['prefix_equal']:,}</div>已核对抉择前记录一致</div></div><nav><a href="#findings">主要发现</a><a href="#ranking">路径变化榜</a><a href="#drill">下钻一个抉择</a><a href="#cases">配对案例</a><a href="#method">方法与下载</a></nav></header>
<section id="findings"><h2>01 / 改变大，不等于选得更好</h2><div class="grid"><div class="panel"><h3>观察到的最大寿命路径变化</h3><p>{html.escape(names[top['decision']])}的平均绝对寿命差为 <b>{top['effect']['abs_life']['mean']:.2f} 年</b>；有方向的均值为 <b>{top['effect']['life']['mean']:+.2f} 年</b>。两者回答不同问题，不能把绝对差叫作延寿。</p></div><div class="panel"><h3>是否真的改了那一次</h3><p>{d['audit']['actual_flip']:,} / 15,000局确认有不同于原自动选择的改选；{d['audit']['prefix_equal']:,}局的出生状态、此前抉择、目标选项和此前日志通过一致性核对。每局只改一次。“暂停片刻”的500次改选，所列终局指标均未改变。</p></div><div class="panel"><h3>这些人不是随机抽样</h3><p>按A报告出现次数取前30类，每类取遇到它的前500个seed。退休、升学、育儿各自筛选了不同人群，不能把排行当作所有人的通用人生建议。</p></div></div><p class="warn">改选会改变后续随机数消耗，差异包含整条人生路径的变化。N1仅作为另一种随机路径扰动参考，不相减、不作置信区间，也不用“高于噪声”宣布因果成立。</p></section>
<section id="ranking"><h2>02 / 路径变化榜</h2><label>排序依据 <select id="sort"><option value="abs_life">平均绝对寿命差：变化有多大</option><option value="life">平均寿命差：是否更长</option><option value="edu_changed">终局学历变化比例</option><option value="job_changed">最后工作变化比例</option><option value="kids_changed">摘要子女数变化比例</option></select></label><div id="rank" class="scroll"></div><p class="note">寿命均值按“改选−原自动”计算；绝对差没有好坏方向。每类500对，类别间重复seed，不能把15,000对当成独立的人。N1只使用该类别中具有对应噪声记录的seed，参考分母另列。较早的抉择有更长时间让后续路径分岔，排名也受改选年龄影响，不是剔除随机影响后的重要性排名。</p></section>
<section id="drill"><h2>03 / 下钻一个抉择</h2><div class="controls"><label>抉择类型 <select id="decision"></select></label><label>观察年龄 <select id="age"><option>24</option><option>30</option><option>35</option><option selected>40</option><option>50</option><option>65</option></select></label></div><div id="about"></div><h3>寿命差分布：改选减原自动</h3><div id="hist"></div><h3>终局类别变化</h3><div id="outcomes" class="scroll"></div><h3>具体从什么改成什么</h3><div id="choices" class="scroll"></div><p class="note">按原选项代码→改选代码分组。同一个代码的职位、人物、金额等具体内容可能不同，标签只展示最常见的最多3种原文示例，不能当作统一治疗。小于30对的组单列提示；这些组不能相互当作随机分配。</p><h3>固定年龄：只看截至该年龄已改选的配对</h3><div id="flow" class="scroll"></div><div id="money" class="scroll"></div><p class="note">“尚未改选”不会混入当期效果；已到改选年龄但快照缺失者不补零。两臂都存活到该年龄的选择仍存在。金额为内部金额×3.5的人民币中国购买力等价值，非汇率、非现实预测；月收入为年收入÷12。净资产包括现金、投资与住房等，差值中位数不等于两臂中位数相减。</p><h3>这500人的出生国家构成</h3><div id="countries" class="chips"></div><p class="note">按原始出生状态归类，保留收养、迁移等后续经历。不同国家构成与不同改选年龄都影响类别之间的可比性。</p></section>
<section id="cases"><h2>04 / 可追溯的分岔案例</h2><p>取平均绝对寿命差最大的5类，每类选择绝对寿命差接近中位位置的一对，再补充“暂停片刻”作为对照案例。不是挑选最戏剧化或最成功的人生。展开后可对照完整日志。</p><div id="caseList"></div></section>
<section id="method"><h2>05 / 样本口径与复算</h2><ul><li>任务选择来自A的全部抉择记录：频次前30类，各取按序遇到的前500个seed。备用选项选全局自动选择次数最少的可用非原选项，并按代码打破平局；同一类别未必都改为同一个选项。</li><li>对照直接复用A的0.8.30完整原始记录。逐份核验任务ID唯一、计划集合一致、原始文件齐全且稳定，以及改选前记录一致。没有重跑昂贵模拟。</li><li>终局学历、工作、子女与伴侣状态是在各自死亡年龄观察。子女数为summary.kids（可能含继子女或已亡故子女），不是亲生出生数。伴侣状态字段在部分早亡人生中缺失，该项只在双方有字段时比较并公开分母。</li><li>噪声使用N1：同一A seed出生后丢弃一个随机数的路径，与本实验在后来某个年龄改选不同。它不构成同时间、同决策的安慰剂对照。未从C2指标中扣除噪声。</li><li>同种子只固定随机起点；本报告可以描述这套引擎的路径敏感性，不能据此推断现实因果收益。</li></ul><p>采集完成：{html.escape(d['finished'])}</p><details><summary>数据指纹</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{html.escape(json.dumps(d['source_hashes'],indent=2))}</pre></details><div id="downloads"></div><p class="note">将两个Python脚本及policy_report.template.html放回项目scripts/，保留A_peers2002、N_noise、C2_flip原始数据；将selection.json放到work/data-run/c2-selection.json。运行 python3 scripts/analyze_flip_report.py，再运行 python3 scripts/build_flip_report.py。</p></section></main>'''
js=r'''<script>const D=__DATA__,NAMES=__NAMES__,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(x,d=2)=>x==null?'—':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:d}),pct=x=>x==null?'—':(100*x).toFixed(1)+'%';
function table(head,rows){return '<table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function rank(){let metric=$('sort').value,rs=[...D.rankings].sort((a,b)=>b.effect[metric].mean-a.effect[metric].mean);$('rank').innerHTML=table(['抉择','实际改选 / 计划','绝对寿命差均值','有方向寿命差均值','寿命相同','学历变','工作变','N1绝对寿命差 / 对数'],rs.map(r=>['<button data-id="'+esc(r.decision)+'">'+esc(NAMES[r.decision])+'</button>',r.executed+' / '+r.planned,num(r.effect.abs_life.mean),num(r.effect.life.mean),pct(r.effect.life_same.mean),pct(r.effect.edu_changed.mean),pct(r.effect.job_changed.mean),num(r.noise.abs_life.mean)+' / '+r.noise.n]));$('rank').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{$('decision').value=b.dataset.id;render();$('drill').scrollIntoView({behavior:'smooth'})}));}
function render(){let id=$('decision').value,age=$('age').value,r=D.rankings.find(x=>x.decision===id);$('about').innerHTML='<h3>'+esc(NAMES[id])+' <small>'+esc(id)+'</small></h3><p>常见标题示例：'+esc(r.title)+'。改选年龄 P10 / 中位 / P90：'+num(r.flip_age.p10)+' / '+num(r.flip_age.median)+' / '+num(r.flip_age.p90)+' 岁；覆盖 '+r.unique_countries+' 个出生国家。</p>';let labels=['≤−20年','−19至−10年','−9至−1年','0年','1至9年','10至19年','≥20年'];$('hist').innerHTML=table(['寿命差','人数','占500对比例'],r.life_hist.map((n,i)=>[labels[i],n,'<div class="bar" style="min-width:220px"><span style="width:'+n/5+'%"></span></div>'+pct(n/500)]));$('outcomes').innerHTML=table(['指标','变化比例','有效配对分母','N1参考比例 / 分母'],[['edu_changed','学历'],['job_changed','最后工作'],['kids_changed','摘要子女数'],['cause_changed','死因代码'],['partner_changed','伴侣状态']].map(([m,l])=>[l,pct(r.effect[m].mean),r.effect[m].n,pct(r.noise[m].mean)+' / '+r.noise[m].n]));$('choices').innerHTML=table(['原选项 → 改选','标签示例：原 → 改','配对数','寿命差均值','绝对寿命差均值'],D.choices.filter(x=>x.decision===id).sort((a,b)=>b.n-a.n).map(x=>[esc(x.auto)+' → '+esc(x.target),'<span style="display:block;max-width:480px;white-space:normal">'+esc(x.auto_labels.join(' / '))+' → '+esc(x.target_labels.join(' / '))+'</span>',x.n+(x.n<30?' ⚠ 小样本':''),num(x.life.mean),num(x.abs_life.mean)]));let a=D.age_rows.find(x=>x.decision===id&&x.age===age);$('flow').innerHTML=table(['计划','尚未改选','已改选但任一缺快照','原臂缺快照','改选臂缺快照','双方快照可比'],[[a.planned,a.not_yet,a.exposed_missing,a.base_missing,a.flip_missing,a.both_observed]]);$('money').innerHTML=table(['原臂净资产中位/元','改选臂净资产中位/元','配对净资产差P10 / 中位 / P90','月收入差中位/元','幸福差中位','健康差中位'],[[num(a.base_nw.median,0),num(a.flip_nw.median,0),num(a.nw_delta.p10,0)+' / '+num(a.nw_delta.median,0)+' / '+num(a.nw_delta.p90,0),num(a.income_delta.median,0),num(a.h_delta.median),num(a.hl_delta.median)]]);$('countries').innerHTML=D.countries.filter(x=>x.decision===id).sort((a,b)=>b.n-a.n).map(x=>'<span>'+esc(x.iso)+' '+x.n+'</span>').join('');}
$('decision').innerHTML=D.rankings.map(r=>'<option value="'+esc(r.decision)+'">'+esc(NAMES[r.decision])+'</option>').join('');$('decision').value=[...D.rankings].sort((a,b)=>b.effect.abs_life.mean-a.effect.abs_life.mean)[0].decision;$('sort').addEventListener('change',rank);['decision','age'].forEach(id=>$(id).addEventListener('change',render));rank();render();
$('caseList').innerHTML=D.cases.map(c=>'<details><summary>'+esc(NAMES[c.decision]+' / '+c.seed+' / '+c.flip_age+'岁：'+c.auto_label+' → '+c.target_label)+'；寿命差 '+num(c.life)+' 年</summary><div class="two">'+c.lives.map(l=>'<div class="panel"><h3>'+esc(l.arm+' · '+l.name)+'</h3><p>终年 '+l.age+' 岁</p><div class="log">'+l.log.map(x=>'<p><b>'+esc(x.a)+'岁</b> '+esc(x.text)+'</p>').join('')+'</div></div>').join('')+'</div></details>').join('');$('downloads').innerHTML=__DOWNLOADS__;</script></body></html>'''
files=[root/'tables'/f for f in ['flip_effect.csv','choice_directions.csv','age_effect.csv','pair_audit.csv','country_mix.csv','selection.json']];sources=['analyze_flip_report.py','build_flip_report.py','policy_report.template.html']
for deploy in [False,True]:
 links=' · '.join(f'<a href="{"c2_"+f.name if deploy else "tables/"+f.name}">{f.name}</a>' for f in files)+'<p>'+' · '.join(f'<a href="{"c2_"+f if deploy else "../../scripts/"+f}">{f}</a>' for f in sources)+'</p>'
 out=head+js.replace('__DATA__',json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')).replace('__NAMES__',json.dumps(names,ensure_ascii=False)).replace('__DOWNLOADS__',json.dumps(links,ensure_ascii=False))
 (pub/'C2_flip.html' if deploy else root/'report.html').write_text(out)
for f in files:shutil.copyfile(f,pub/('c2_'+f.name))
for f in sources:shutil.copyfile(ROOT/'scripts'/f,pub/('c2_'+f))
print('Built C2',len(out))
